import { readFileSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

// Bundled TLD data, generated by `npm run update-tlds` from IANA (which TLDs exist),
// the IANA RDAP bootstrap (where to ask about them) and Porkbun's public price list
// (which ones the public can buy, and roughly what they cost).

export interface TldInfo {
  tld: string; // without the dot
  rdap?: string;
  reg?: number; // first-year list price, USD
  renew?: number; // renewal list price, USD
}

export type TldScope = 'purchasable' | 'all';

interface TldFile {
  generated: string;
  ianaVersion: string;
  suffixes?: Record<string, { reg: number; renew?: number }>;
  tlds: Record<string, Omit<TldInfo, 'tld'>>;
}

// Resolved from this file, not process.cwd(), so the server works wherever it is launched from
const PACKAGE_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

// Exist in the root zone but cannot be registered by the public
const BLACKLISTED_TLDS = new Set(['data', 'pg']);

// Open ccTLDs that are popular for domain hacks but missing from the price list
const UNPRICED_OPEN_TLDS = ['ly', 'so', 'is', 'im', 'cx', 'st', 'gs', 'ms', 'vg', 'tc', 'nu', 'ch', 'li', 'at', 'be', 'es', 'se', 'pl', 'cz', 'pt'];

const FALLBACK_TLDS = ['com', 'net', 'org', 'io', 'ai', 'app', 'co', 'dev'];

function load(): { info: Map<string, TldInfo>; suffixes: Map<string, TldInfo>; generated: string } {
  const info = new Map<string, TldInfo>();
  const suffixes = new Map<string, TldInfo>();
  try {
    const file = JSON.parse(readFileSync(join(PACKAGE_ROOT, 'data', 'tlds.json'), 'utf-8')) as TldFile;
    for (const [tld, entry] of Object.entries(file.tlds)) info.set(tld, { tld, ...entry });
    for (const [suffix, entry] of Object.entries(file.suffixes ?? {})) suffixes.set(suffix, { tld: suffix, ...entry });
    return { info, suffixes, generated: file.generated };
  } catch {
    // Fall back to the plain IANA list, then to a minimal built-in set
    try {
      readFileSync(join(PACKAGE_ROOT, 'tlds.txt'), 'utf-8')
        .split('\n')
        .map(line => line.trim().toLowerCase().replace(/^\./, ''))
        .filter(line => line && !line.startsWith('#'))
        .forEach(tld => info.set(tld, { tld }));
    } catch {
      // ignore
    }
    if (info.size === 0) FALLBACK_TLDS.forEach(tld => info.set(tld, { tld }));
    return { info, suffixes, generated: 'unknown' };
  }
}

const { info: TLD_INFO, suffixes: SUFFIX_INFO, generated: DATA_GENERATED } = load();
const HAS_PRICES = [...TLD_INFO.values()].some(t => t.reg !== undefined);

export const tldDataDate = DATA_GENERATED === 'unknown' ? 'unknown' : DATA_GENERATED.slice(0, 10);

const clean = (tld: string) => tld.toLowerCase().replace(/^\./, '');

export function getTldInfo(tld: string): TldInfo | undefined {
  return TLD_INFO.get(clean(tld));
}

export function isKnownTld(tld: string): boolean {
  return TLD_INFO.has(clean(tld));
}

export function isPurchasable(tld: string): boolean {
  const key = clean(tld);
  const entry = TLD_INFO.get(key);
  if (!entry || BLACKLISTED_TLDS.has(key)) return false;
  // Without price data there is nothing to tell open TLDs from closed ones
  if (!HAS_PRICES) return true;
  return entry.reg !== undefined || UNPRICED_OPEN_TLDS.includes(key);
}

/** TLDs without the leading dot. 'purchasable' drops brand and otherwise closed TLDs. */
export function listTlds(scope: TldScope = 'purchasable'): TldInfo[] {
  // Internationalised (punycode) TLDs can still be checked, but are left out of lists and suggestions
  const all = [...TLD_INFO.values()].filter(t => !BLACKLISTED_TLDS.has(t.tld) && !t.tld.startsWith('xn--'));
  return scope === 'all' ? all : all.filter(t => isPurchasable(t.tld));
}

export function tldType(tld: string): 'country' | 'generic' {
  const key = clean(tld);
  // Two-letter TLDs are country codes; internationalised ones are a mix and treated as generic
  return /^[a-z]{2}$/.test(key) ? 'country' : 'generic';
}

/**
 * Typical price for a TLD ("io") or a full domain ("shop.co.uk"), e.g. "$11.81/yr" or
 * "$20.91 first yr, $51.80/yr after". Undefined when no list price is known.
 */
export function formatPrice(tldOrDomain: string): string | undefined {
  const labels = clean(tldOrDomain).split('.');
  // Second-level suffixes such as co.uk have their own price
  const entry = (labels.length >= 3 ? SUFFIX_INFO.get(labels.slice(-2).join('.')) : undefined)
    ?? TLD_INFO.get(labels[labels.length - 1]);
  if (entry?.reg === undefined) return undefined;
  const usd = (n: number) => `$${n.toFixed(2)}`;
  if (entry.renew === undefined || entry.renew === entry.reg) return `${usd(entry.reg)}/yr`;
  return `${usd(entry.reg)} first yr, ${usd(entry.renew)}/yr after`;
}
